                    <template #option="scope">
                      <div :key="scope.opt.value">
                        <div v-if="scope.opt.group && scope.opt.group !== compareLeftOptions[scope.index - 1]?.group" class="rb-opt-group" :class="{ 'rb-opt-group--first': scope.index === 0 }">{{ scope.opt.group }}</div>
