                    </template>
                  </q-select>
                </div>
                <div>
                  <label class="rb-label">{{ $t('must_be') }}</label>
                  <q-select outlined dense emit-value map-options class="back-white" v-model="model.compare_op" :options="compareOpOptions" :readonly="isReadOnly" />
