                <div>
                  <label class="rb-label">{{ $t('field_or_value') }}</label>
                  <q-select outlined dense use-input input-debounce="0" emit-value map-options class="back-white" v-model="model.compare_right" :options="compareRightOptions" :readonly="isReadOnly" @filter="filterCompareRight" popup-content-class="rb-field-popup">
                    <template #option="scope">
                      <div :key="scope.opt.value">
                        <div v-if="scope.opt.group && scope.opt.group !== compareRightOptions[scope.index - 1]?.group" class="rb-opt-group" :class="{ 'rb-opt-group--first': scope.index === 0 }">{{ scope.opt.group }}</div>
                        <q-item v-bind="scope.itemProps"><q-item-section>{{ scope.opt.label }}</q-item-section></q-item>
