        <q-card-section>
          <q-btn-toggle
            v-model="testDocMode"
            spread no-caps unelevated
            toggle-color="primary"
            color="white"
            text-color="grey-8"
            class="rb-test-toggle q-mb-md"
            :options="[
              { label: $t('test_by_document_id'), value: 'id' },
              { label: $t('test_by_document_json'), value: 'json' },
