          />

          <q-input
            v-if="testDocMode === 'id'"
            outlined dense autofocus
            class="back-white"
            v-model="testDocId"
            :placeholder="$t('test_document_id_placeholder')"
          />
          <!-- Ace JSON editor (same component the form builder uses for
               "Edit JSON"). Value is pulled from the ref on run, not v-model;
               keyed on dialog-open so it re-initialises empty each time. -->
          <LayoutJsonEditor
            v-else-if="testDialogOpen"
            ref="testJsonEditor"
            :key="testJsonKey"
            :json-data="{}"
            class="rb-test-json"
          />
        </q-card-section>

        <!-- Result panel — populated after a run; the dialog stays open so the
             user can adjust the document and re-run without losing context. -->
        <q-card-section v-if="testResultView" class="q-pt-none">
          <div class="rb-test-result" :class="`rb-test-result--${testResultView.status}`">
            <div class="row no-wrap items-start q-gutter-sm">
              <q-icon :name="statusIcon(testResultView.status)" :color="statusColor(testResultView.status)" size="sm" />
              <div>
                <div class="text-subtitle2">
                  {{ testResultView.status === 'passed' ? $t('test_result_passed') : testResultView.status === 'failed' ? $t('test_result_failed') : $t('test_result_skipped') }}
                </div>
                <div v-if="testResultView.message" class="text-caption text-grey-7">{{ testResultView.message }}</div>
                <div v-else-if="testResultView.status === 'skipped'" class="text-caption text-grey-7">{{ $t('test_result_skipped_hint') }}</div>
              </div>
            </div>

            <!-- Line-scoped rules evaluate per table row; show the roll-up and
                 a compact breakdown of each row's outcome. -->
            <template v-if="testResultView.rows.length">
              <div class="text-caption text-weight-medium q-mt-sm q-mb-xs">
                {{ $t('test_result_rows_summary', { passed: testResultView.passedCount, total: testResultView.matchedCount }) }}
              </div>
              <div v-for="row in testResultView.rows" :key="row.row_index" class="row no-wrap items-center q-gutter-xs text-caption q-py-xs">
                <q-icon :name="statusIcon(row.status)" :color="statusColor(row.status)" size="xs" />
                <span class="text-weight-medium">{{ $t('test_result_row', { index: row.row_index + 1 }) }}</span>
                <span class="text-grey-7">
                  {{ row.message || (row.status === 'passed' ? $t('test_result_passed') : row.status === 'skipped' ? $t('test_result_skipped') : $t('test_result_failed')) }}
                </span>
              </div>
            </template>
          </div>
        </q-card-section>

        <q-card-actions align="right" class="q-px-md q-pb-md">
          <q-btn flat :label="$t('close')" v-close-popup />
          <f-btn color="primary" icon="play_arrow" :label="testResult ? $t('test_run_again') : $t('test_rule')" :loading="testing" @click="executeTest" />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import { customValidationRulesApiService, documentTypeApiService } from 'src/services';
import type { CustomValidationRule, TestValidationRulePayload, TestValidationRuleResult } from 'src/services/settings/CustomValidationRulesApiService';
import {
  emptyModel,
  fromApiRule,
  slugify,
  assembleApiCore,
  buildFieldOptions,
  loadLovValueOptions,
  buildTargetFieldOptions,
  loadHeaderFieldOptions,
  loadDocOriginOptions,
  OP_OPTIONS,
  COMPARE_OP_OPTIONS,
  renderRuleHint,
  ASSERTION_CARDS,
  CUSTOM_PATH_OPTION,
  DOC_ORIGIN_FIELD,
  DOC_EXTRACTION_METHOD_FIELD,
  expressionFunctions,
  matchExprToken,
  applyExprEdit,
  nextSuggestionIndex,
  isExactSingleMatch,
  type BuilderModel,
  type FieldOption,
  type ExprSuggestion,
} from './rule-builder-model';
import { useRuleKey } from './useRuleKey';
import { storeToRefs } from 'pinia';
import { useFieldValuesSettingsStore } from 'src/store/main';
import { useDropdownStore } from 'src/store/Dropdown/dropdown.store';
import ConditionGroup from './ConditionGroup.vue';
import LayoutJsonEditor from 'src/components/JsonEditor.vue';

export default defineComponent({
  name: 'CustomValidationRuleBuilder',
  components: { ConditionGroup, LayoutJsonEditor },
  data() {
    return {
      doc_type_key: '',
      opOptions: OP_OPTIONS,
      compareOpOptions: COMPARE_OP_OPTIONS,
      // Header fields are fetched once and cached. Line columns are table-
      // specific: a doc type can have several tables, so the user picks one
      // (Table name) and its columns are loaded on demand into cachedLineColumns.
      cachedHeaderFields: [] as FieldOption[],
      cachedLineColumns: [] as FieldOption[],
      fieldsLoaded: false,
      // Document tables for this doc type (line scope) and the selected one.
      // Selecting a table loads its columns for the row.* pickers/autocomplete.
      tableOptions: [] as FieldOption[],
      selectedTable: '',
      loadingTables: false,
      loadingColumns: false,
      // True while an existing rule is being applied, so the scope watcher
      // doesn't clear the rule's saved target_field.
      applyingRule: false,
      // Test dialog: the user supplies EITHER a document id OR document JSON.
      testDialogOpen: false,
      testDocMode: 'id' as 'id' | 'json',
      testDocId: '',
      // Bumped each time the dialog opens so the keyed Ace editor re-inits empty.
      testJsonKey: 0,
      // Last dry-run result, rendered inline in the dialog. Null until the
      // first run; cleared when the inputs change or the dialog re-opens.
      testResult: null as TestValidationRuleResult | null,
      // Arithmetic-expression autocomplete. Opens when the caret sits on a
      // `header.` / `row.` / `doc.` field token or a bare function-name word;
      // the token's [start,end) span is what a picked suggestion replaces.
      exprSuggestOpen: false,
      exprSuggestions: [] as ExprSuggestion[],
      // Highlighted suggestion for arrow-key navigation; Enter applies it.
      exprSuggestActive: 0,
      exprTokenStart: 0,
      exprTokenEnd: 0,
      // The zero-size element the menu anchors to; moved to the caret's pixel
      // position on each keystroke. Bound as the q-menu :target.
      exprCaretTarget: null as HTMLElement | null,
      // Document-origin value options (doc.doc_origin), loaded once from the
      // shared language-origin store and handed to the condition pickers.
      originOptions: [] as FieldOption[],
      subOrgOptions: [] as FieldOption[],
      lovValueOptions: {} as Record<string, FieldOption[]>,
      // The full field list for the current scope, rebuilt from the cache. The
      // condition pickers filter their own copies of this.
      allFields: [] as FieldOption[],
      // What the field-comparison pickers may offer: the SAME mapped fields
      // without the Advanced "Custom JSON path" sentinel. Held separately from
      // allFields because both the initial list and the filtered one have to be
      // drawn from it — filtering from allFields put the sentinel back.
      compareFields: [] as FieldOption[],
      // Each picker owns its list so filtering one never disturbs another.
      compareLeftOptions: [] as FieldOption[],
      compareRightOptions: [] as FieldOption[],
      // Target-field picker (bare field name, scoped to the rule level).
      allTargetFields: [] as FieldOption[],
      targetFieldOptions: [] as FieldOption[],
      loadingFields: false,
      // List-of-Values picker (allowed_values check, LOV source). The master
      // list comes from the store; lovOptions is the filtered copy the select binds.
      lovOptions: [] as string[],
      lovLoading: false,
    };
  },
  computed: {
    isEdit(): boolean {
      return !!this.rule_id;
    },
    // Rule-level toggle: three backend scopes. Labels are translated per render
    // so a locale switch updates them.
    scopeToggleOptions(): { label: string; value: string }[] {
      return [
        { label: this.$t('rule_level_header'), value: 'header' },
        { label: this.$t('rule_level_line'), value: 'line' },
        { label: this.$t('rule_level_table'), value: 'table' },
      ];
    },
    severityToggleOptions(): { label: string; value: string }[] {
      return [
        { label: this.$t('error'), value: 'error' },
        { label: this.$t('warning'), value: 'warning' },
      ];
    },
    // Only line rules attach to a table column; header and whole-table rules
    // land the error on a header field.
    attachErrorLabel(): string {
      return this.model.scope === 'line'
        ? this.$t('attach_error_to_column')
        : this.$t('attach_error_to_field');
    },
    // Whole-table rules only support the arithmetic Formula; other scopes get
    // the full set.
    assertionCards(): typeof ASSERTION_CARDS {
      if (this.model.scope === 'table') {
        return ASSERTION_CARDS.filter((c) => c.type === 'arithmetic');
      }
      return ASSERTION_CARDS;
    },
    // The bottom hint reflects the selected level's semantics (see backend
    // scope constraints); rendered from a trusted, escaped i18n string.
    levelHintHtml(): string {
      const key =
        this.model.scope === 'line'
          ? 'rule_level_hint_line'
          : this.model.scope === 'table'
            ? 'rule_level_hint_table'
            : 'rule_level_hint_header';
      return renderRuleHint(this.$t(key));
    },
    // The store seeds a leading '' entry; drop empties for the picker.
    lovMaster(): string[] {
      return ((this.lov_list as unknown as string[]) || []).filter((x) => !!x);
    },
    // Fully-namespaced field tokens offered by the expression autocomplete.
    // doc.* apply to any scope; header.* always; row.* only for line (per-row)
    // rules — on whole-table rules rows are reachable only inside aggregates.
    exprFieldTokens(): FieldOption[] {
      const toks: FieldOption[] = [
        { value: DOC_ORIGIN_FIELD, label: this.$t('document_origin') },
        { value: DOC_EXTRACTION_METHOD_FIELD, label: this.$t('extraction_method') },
      ];
      this.cachedHeaderFields.forEach((f) => toks.push({ value: `header.${f.value}`, label: f.label }));
      if (this.model.scope === 'line') {
        this.cachedLineColumns.forEach((f) => toks.push({ value: `row.${f.value}`, label: f.label }));
      }
      return toks;
    },
    // Insert chips shown under the expression field: the scope-valid functions
    // followed by the namespace prefixes. Clicking one drops it at the caret.
    // row. is only offered on line rules (bare row.* is invalid whole-table).
    exprChips(): { text: string; insert: string; caretBack: number }[] {
      const chips = expressionFunctions(this.model.scope).map((f) => ({
        text: `${f.value}()`,
        insert: `${f.value}()`,
        caretBack: 1,
      }));
      chips.push({ text: 'header.', insert: 'header.', caretBack: 0 });
      if (this.model.scope === 'line') {
        chips.push({ text: 'row.', insert: 'row.', caretBack: 0 });
      }
      chips.push({ text: 'doc.', insert: 'doc.', caretBack: 0 });
      return chips;
    },
    // Normalise the raw API result into a single display model the template
    // renders: an overall status (passed / failed / skipped), a headline and
    // detail line, plus per-row outcomes for line-scoped rules.
    testResultView(): {
      status: 'passed' | 'failed' | 'skipped';
      severity: string;
      message: string | null;
      rows: {
        row_index: number;
        status: 'passed' | 'failed' | 'skipped';
        message: string | null;
      }[];
      passedCount: number;
      matchedCount: number;
    } | null {
      const r = this.testResult;
      if (!r) return null;

      const rowStatus = (row: { scope_matched: boolean | null; passed: boolean | null }) => {
        if (row.scope_matched === false) return 'skipped' as const;
        return row.passed === false ? ('failed' as const) : ('passed' as const);
      };

      const rawRows = Array.isArray(r.rows) ? r.rows : [];
      const rows = rawRows.map((row) => ({
        row_index: row.row_index,
        status: rowStatus(row),
        message: row.message,
      }));

      // Line scope: aggregate the per-row outcomes.
      if (rows.length) {
        const matched = rows.filter((row) => row.status !== 'skipped');
        const failed = matched.filter((row) => row.status === 'failed');
        const status = !matched.length ? 'skipped' : failed.length ? 'failed' : 'passed';
        return {
          status,
          severity: r.severity,
          message: failed.find((row) => row.message)?.message || r.message,
          rows,
          passedCount: matched.length - failed.length,
          matchedCount: matched.length,
        };
      }

      // Header / table scope: single evaluation.
      const status = r.scope_matched === false ? 'skipped' : r.passed === false ? 'failed' : 'passed';
      return {
        status,
        severity: r.severity,
        message: r.message,
        rows: [],
        passedCount: 0,
        matchedCount: 0,
      };
    },
  },
  watch: {
    // Customizing a system default navigates from this same route to the new
    // override's id. The settings router-view is unkeyed, so Vue reuses this
    // instance and mounted() does not re-run — reload the rule ourselves when
    // the id param changes (fields/tables are already cached from mount).
    '$route.params.rule_id'(newId: string) {
      const id = String(newId || '');
      if (id && id !== this.rule_id) {
        this.rule_id = id;
        this.loadForEdit();
      }
    },
    // Scope drives which sections are shown. Only re-group the already
    // cached fields locally — no re-fetch — and clear the current target
    // selection (a header field is not a line column).
    'model.scope'() {
      if (this.applyingRule) return;
      this.model.target_field = '';
      this.rebuildFieldOptions();
      this.ensureTableSelected();
      // Whole-table rules only offer the Formula card; keep the choice in sync.
      if (this.model.scope === 'table') {
        this.model.assertion_type = 'arithmetic';
      }
    },
    // Leaving the arithmetic card unmounts the textarea; make sure the
    // autocomplete doesn't re-open with stale suggestions on return.
    'model.assertion_type'() {
      this.exprSuggestOpen = false;
    },
  },
  mounted() {
    this.doc_type_key = String(this.$route.params.doc_type || '');
    this.rule_id = String(this.$route.params.rule_id || '');
    this.loadFieldsOnce().then(() => {
      this.rebuildFieldOptions();
      this.loadLovValues();
    });
    // Default-select a table (line scope) so row.* columns are available at once.
    this.loadTables().then(() => this.ensureTableSelected());
    this.loadLov();
    this.loadOrigins();
    this.loadSubOrgs();
    if (this.isEdit) {
      this.loadForEdit();
    }
  },
  methods: {
    async loadForEdit() {
      // Prefer the row handed over via router state (from the list) to skip a
      // round-trip. Otherwise fetch just this one rule by id — no need to load
      // every rule for the doc type on a deep link / refresh.
      const stateRule = (history.state && history.state.rule) as CustomValidationRule | undefined;
      if (stateRule && stateRule.id === this.rule_id) {
        this.applyRule(stateRule);
        return;
      }
      try {
        this.saving = true;
        const rule = await customValidationRulesApiService.getById(this.rule_id);
        if (rule && rule.id) {
          this.applyRule(rule);
        } else {
          notify.error(this.$t('rule_not_found'));
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.saving = false;
      }
    },
    applyRule(rule: CustomValidationRule) {
      this.isReadOnly = rule.source === 'system_default';
      // Loading an existing rule sets scope programmatically — don't let the
      // scope watcher wipe the rule's saved target_field.
      this.applyingRule = true;
      this.model = fromApiRule(rule);
      this.$nextTick(() => {
        this.applyingRule = false;
        this.rebuildFieldOptions();
        // Restore the rule's own table (loading its row.* columns), else default.
        if (this.model.scope === 'line' && this.model.table_name) {
          this.onTableSelected(this.model.table_name);
        } else {
          this.ensureTableSelected();
        }
      });
    },
    // Fetch the header fields ONCE and cache them. Line columns are loaded
    // separately per selected table (loadColumnsForTable), not here.
    async loadFieldsOnce() {
      if (this.fieldsLoaded) return;
      try {
        this.loadingFields = true;
        this.cachedHeaderFields = await this.loadHeaderFields();
        this.fieldsLoaded = true;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loadingFields = false;
      }
    },
    // Re-group the cached fields for the current scope (no network). Each
    // picker gets its own copy so filtering one never mutates the shared source.
    rebuildFieldOptions() {
      const lineColumns = this.model.scope === 'line' ? this.cachedLineColumns : [];
      const base = buildFieldOptions(this.model.scope, this.cachedHeaderFields, lineColumns);
      // Field-comparison pickers use mapped fields only — no Custom JSON path.
      // Their filters read compareFields, so the exclusion survives typing.
      this.compareFields = base;
      this.compareLeftOptions = base.slice();
      this.compareRightOptions = base.slice();
      // The "Applies when" condition picker additionally offers the Advanced
      // "Custom JSON path" escape hatch as the last option.
      this.allFields = [
        ...base,
        { value: CUSTOM_PATH_OPTION, label: this.$t('custom_json_path'), group: this.$t('advanced') },
      ];
      this.allTargetFields = buildTargetFieldOptions(this.model.scope, this.cachedHeaderFields, this.cachedLineColumns);
      this.targetFieldOptions = this.allTargetFields.slice();
    },
    // Values of every list-of-values referenced by the loaded header fields, so
    // a condition on a LOV-backed field offers its allowed values. Non-fatal:
    // the row falls back to a free-text box.
    async loadLovValues() {
      try {
        this.lovValueOptions = await loadLovValueOptions(this.cachedHeaderFields);
      } catch (err) {
        logError(err);
      }
    },
    // Doc-origin values for the doc.doc_origin condition picker — loaded once
    // through the shared model helper (same source main.vue uses).
    async loadOrigins() {
      try {
        this.originOptions = await loadDocOriginOptions();
      } catch (err) {
        logError(err);
      }
    },
    // Sub-organizations for the doc.sub_org_id condition picker — loaded once
    // from the shared dropdown store (mirrors loadOrigins).
    async loadSubOrgs() {
      try {
        const store = useDropdownStore();
        await store.getSubOrgsList();
        this.subOrgOptions = (store.subOrgList as dynamicObj[])
          .filter((o) => o && o.value)
          .map((o) => ({ value: String(o.value), label: String(o.label ?? o.value) }));
      } catch (err) {
        logError(err);
      }
    },
    async loadHeaderFields(): Promise<FieldOption[]> {
      // Shared loader (rule-builder-model) — the layout-selection-rule drawer
      // fetches its header fields through the same path.
      return loadHeaderFieldOptions(this.doc_type_key);
    },
    // Load the document tables for this doc type into the Table name picker.
    async loadTables() {
      if (!this.doc_type_key) return;
      try {
        this.loadingTables = true;
        const res = await documentTypeApiService.getTable(this.doc_type_key);
        const list = ((res && res.data) || []) as dynamicObj[];
        this.tableOptions = list
          .filter((t) => t && t.table_name)
          .map((t) => ({ value: String(t.table_name), label: String(t.table_name) }));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loadingTables = false;
      }
    },
    // Fetch the columns of one table as BARE field options (the row. namespace
    // is added at build time). Calls the API directly rather than the shared
    // store loader, whose cache guard throws when switching between tables.
    async loadColumnsForTable(tableName: string): Promise<FieldOption[]> {
      if (!tableName) return [];
      const res = await documentTypeApiService.getDocumentTableColumns(tableName);
      const columns = ((res && res.data) || []) as dynamicObj[];
      return columns
        .filter((col) => col && col.column_name)
        .map((col) => {
          const colType = col.column_type || col.dataType;
          return {
            value: String(col.column_name),
            label: String(col.column_name),
            type: colType ? String(colType) : undefined,
          };
        });
    },
    // Table name picker changed — load that table's columns and rebuild the
    // row.* field options (condition picker, target field, expression tokens).
    async onTableSelected(tableName: string | null) {
      this.selectedTable = tableName || '';
      // Mirror into the model so the table round-trips on save/test.
      this.model.table_name = this.selectedTable;
      if (!this.selectedTable) {
        this.cachedLineColumns = [];
        this.rebuildFieldOptions();
        return;
      }
      try {
        this.loadingColumns = true;
        this.cachedLineColumns = await this.loadColumnsForTable(this.selectedTable);
        this.rebuildFieldOptions();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loadingColumns = false;
      }
    },
    // Default the Table name picker to the first table (line scope) so row.*
    // columns are available without an extra click; a no-op once one is chosen.
    ensureTableSelected() {
      if (this.model.scope !== 'line' || this.selectedTable || !this.tableOptions.length) return;
      this.onTableSelected(this.tableOptions[0].value);
    },
    // The two field-comparison pickers filter independently into their own
    // list so filtering one never disturbs the other's options / selection.
    // Both filter compareFields, NOT allFields: a comparison operand has to be a
    // real mapped field, and allFields carries the Custom JSON path sentinel.
    filterCompareLeft(val: string, update: (cb: () => void) => void) {
      update(() => {
        this.compareLeftOptions = this.matchFields(this.compareFields, val);
      });
    },
    filterCompareRight(val: string, update: (cb: () => void) => void) {
      update(() => {
        this.compareRightOptions = this.matchFields(this.compareFields, val);
      });
    },
    filterTargetFields(val: string, update: (cb: () => void) => void) {
      update(() => {
        this.targetFieldOptions = this.matchFields(this.allTargetFields, val);
      });
    },
    // Load the saved List-of-Values names (shared store — same source the
    // field-settings pages use). Seeds the picker once fetched.
    async loadLov() {
      try {
        this.lovLoading = true;
        await this.getLovList();
        this.lovOptions = this.lovMaster.slice();
      } catch (err) {
        logError(err);
      } finally {
        this.lovLoading = false;
      }
    },
    filterLov(val: string, update: (cb: () => void) => void) {
      update(() => {
        const needle = val.toLowerCase();
        this.lovOptions = needle
          ? this.lovMaster.filter((x: string) => x.toLowerCase().includes(needle))
          : this.lovMaster.slice();
      });
    },
    // Filter a flat list by needle (label or namespaced value). Always returns
    // a NEW array so the bound q-select options never accumulate across cycles.
    matchFields(list: FieldOption[], val: string): FieldOption[] {
      const needle = val.toLowerCase();
      if (!needle) return list.slice();
      return list.filter((f) => f.label.toLowerCase().includes(needle) || f.value.toLowerCase().includes(needle));
    },
    // error_code is an UPPER_SNAKE machine key (e.g. FORMAT_MISMATCH).
    onErrorCodeInput(val: string | number | null) {
      this.model.error_code = String(val ?? '').toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_+/, '');
    },
    validate(): boolean {
      if (!this.model.display_name.trim()) {
        notify.warning(this.$t('name_required'));
        return false;
      }
      if (!this.model.target_field) {
        notify.warning(this.$t('field_required'));
        return false;
      }
      return true;
    },
    async save() {
      if (this.isReadOnly) {
        return;
      }
      if (!this.validate()) {
        return;
      }
      try {
        this.saving = true;
        const core = assembleApiCore(this.model);
        // Save & activate — this action turns the rule on.
        core.is_active = true;
        if (this.isEdit) {
          await customValidationRulesApiService.update(this.rule_id, core);
        } else {
          // rule_key is a machine key derived from the name for new rules
          // (the field is read-only; the user never types it).
          const rule_key = this.model.rule_key || slugify(this.model.display_name);
          await customValidationRulesApiService.create({
            ...core,
            doc_type: this.doc_type_key,
            scope: this.model.scope,
            rule_key,
          });
        }
        notify.success(this.$t('MSG_SAVE'));
        this.goBack();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.saving = false;
      }
    },
    // Resolve the native <textarea> behind the expression q-input.
    exprTextarea(): HTMLTextAreaElement | null {
      const comp = this.$refs.exprInput as { $el?: HTMLElement } | undefined;
      return (comp?.$el?.querySelector('textarea') as HTMLTextAreaElement) || null;
    },
    // Recompute suggestions as the user types — but not on the navigation keys,
    // which are handled in keydown and must not reset the highlighted item.
    onExprKeyup(e: KeyboardEvent) {
      if (['ArrowDown', 'ArrowUp', 'Enter', 'Escape', 'Tab'].includes(e.key)) return;
      this.refreshExprSuggest();
    },
    // While the suggestion menu is open, arrow keys move the highlight, Enter/Tab
    // pick the highlighted item, and Escape closes it. Each is prevented from its
    // default (caret move / newline / focus change) so it drives the menu instead.
    onExprKeydown(e: KeyboardEvent) {
      if (!this.exprSuggestOpen || this.exprSuggestions.length === 0) return;
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        this.exprSuggestActive = nextSuggestionIndex(this.exprSuggestActive, this.exprSuggestions.length, 1);
        this.scrollExprActiveIntoView();
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        this.exprSuggestActive = nextSuggestionIndex(this.exprSuggestActive, this.exprSuggestions.length, -1);
        this.scrollExprActiveIntoView();
      } else if (e.key === 'Enter' || e.key === 'Tab') {
        e.preventDefault();
        this.applyExprSuggestion(this.exprSuggestions[this.exprSuggestActive]);
      } else if (e.key === 'Escape') {
        e.preventDefault();
        this.exprSuggestOpen = false;
      }
    },
    // Keep the highlighted row visible when navigating a scrolled menu. The menu
    // is teleported to <body>, so query it globally (only one is ever open).
    scrollExprActiveIntoView() {
      this.$nextTick(() => {
        const el = document.querySelector('.rb-expr-suggest .rb-expr-suggest--active');
        (el as HTMLElement | null)?.scrollIntoView({ block: 'nearest' });
      });
    },
    // Inspect the text left of the caret: on a `header.`/`row.`/`doc.` token
    // offer matching fields; on a bare word offer matching functions; else
    // close the menu.
    refreshExprSuggest() {
      if (this.isReadOnly) return;
      const ta = this.exprTextarea();
      const expr = this.model.expression || '';
      const caret = ta ? ta.selectionStart ?? expr.length : expr.length;
      const hit = matchExprToken(expr.slice(0, caret));
      if (!hit) {
        this.exprSuggestOpen = false;
        return;
      }
      this.exprTokenStart = hit.start;
      this.exprTokenEnd = caret;
      const pool = hit.kind === 'field' ? this.exprFieldTokens : expressionFunctions(this.model.scope);
      this.exprSuggestions = pool
        .filter((t) => t.value.toLowerCase().startsWith(hit.token))
        .slice(0, 50);
      // Typing rebuilds the list, so re-highlight the first item.
      this.exprSuggestActive = 0;
      // Nothing to add if the sole suggestion is exactly what's already typed.
      const shouldOpen =
        this.exprSuggestions.length > 0 &&
        !isExactSingleMatch(this.exprSuggestions.map((s) => s.value), hit.token);
      // Move the anchor to the START of the token so the menu drops from the
      // cursor, then (re)position an already-open menu for the new coords.
      if (shouldOpen && ta) this.positionExprAnchor(ta, this.exprTokenStart);
      this.exprSuggestOpen = shouldOpen;
      if (shouldOpen) {
        this.$nextTick(() => (this.$refs.exprMenu as { updatePosition?: () => void } | undefined)?.updatePosition?.());
      }
    },
    // Park the zero-size caret anchor over the textarea at the pixel position of
    // `pos`, expressed relative to the .rb-expr-wrap container.
    positionExprAnchor(ta: HTMLTextAreaElement, pos: number) {
      const anchor = this.$refs.exprCaret as HTMLElement | undefined;
      if (!anchor || !anchor.parentElement) return;
      this.exprCaretTarget = anchor;
      const wrapRect = anchor.parentElement.getBoundingClientRect();
      const taRect = ta.getBoundingClientRect();
      const c = this.caretCoordinates(ta, pos);
      anchor.style.left = `${taRect.left - wrapRect.left + c.left - ta.scrollLeft}px`;
      anchor.style.top = `${taRect.top - wrapRect.top + c.top - ta.scrollTop}px`;
      anchor.style.height = `${c.height}px`;
    },
    // Compute the caret's {top,left,height} within a textarea by mirroring its
    // text and styles into a hidden div and measuring a marker span. Standard
    // textarea-caret-position technique.
    caretCoordinates(el: HTMLTextAreaElement, position: number): { top: number; left: number; height: number } {
      const div = document.createElement('div');
      const style = div.style as unknown as Record<string, string>;
      const computed = window.getComputedStyle(el);
      const props = [
        'boxSizing', 'width', 'height', 'overflowX', 'overflowY',
        'borderTopWidth', 'borderRightWidth', 'borderBottomWidth', 'borderLeftWidth',
        'paddingTop', 'paddingRight', 'paddingBottom', 'paddingLeft',
        'fontStyle', 'fontVariant', 'fontWeight', 'fontStretch', 'fontSize',
        'lineHeight', 'fontFamily', 'textAlign', 'textTransform', 'textIndent',
        'letterSpacing', 'wordSpacing', 'tabSize',
      ];
      style.whiteSpace = 'pre-wrap';
      style.wordWrap = 'break-word';
      style.position = 'absolute';
      style.visibility = 'hidden';
      props.forEach((p) => {
        style[p] = computed.getPropertyValue(p.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase()));
      });
      div.textContent = el.value.substring(0, position);
      const span = document.createElement('span');
      // Non-empty so the span has a box even at end of text.
      span.textContent = el.value.substring(position) || '.';
      div.appendChild(span);
      document.body.appendChild(div);
      const coords = {
        top: span.offsetTop + parseInt(computed.borderTopWidth || '0', 10),
        left: span.offsetLeft + parseInt(computed.borderLeftWidth || '0', 10),
        height: parseInt(computed.lineHeight || '0', 10) || parseInt(computed.fontSize || '16', 10),
      };
      document.body.removeChild(div);
      return coords;
    },
    // Replace the token under the caret with the picked suggestion. A function
    // is inserted as `name()` with the caret parked between the parens so the
    // next `row.` keystrokes autocomplete; a field is inserted verbatim.
    applyExprSuggestion(opt: ExprSuggestion) {
      const insert = opt.fn ? `${opt.value}()` : opt.value;
      const caretBack = opt.fn ? 1 : 0;
      this.commitExprEdit(this.exprTokenStart, this.exprTokenEnd, insert, caretBack);
    },
    // Insert an expression snippet (a chip) at the caret, or at the end when the
    // field is not focused.
    insertExprChip(insert: string, caretBack: number) {
      if (this.isReadOnly) return;
      const ta = this.exprTextarea();
      const expr = this.model.expression || '';
      const at = ta ? ta.selectionStart ?? expr.length : expr.length;
      this.commitExprEdit(at, at, insert, caretBack);
    },
    // Apply a pure splice to the expression, close the menu, then restore focus
    // and caret and re-run the suggester (so `header.` etc. opens the field menu).
    commitExprEdit(start: number, end: number, insert: string, caretBack: number) {
      const { expression, caret } = applyExprEdit(this.model.expression || '', start, end, insert, caretBack);
      this.model.expression = expression;
      this.exprSuggestOpen = false;
      this.$nextTick(() => {
        const ta = this.exprTextarea();
        if (ta) {
          ta.focus();
          ta.setSelectionRange(caret, caret);
        }
        this.refreshExprSuggest();
      });
    },
    // Map a result status to its Quasar icon / colour (colours resolve in both
    // light and dark themes, so no per-theme CSS is needed).
    statusIcon(status: 'passed' | 'failed' | 'skipped'): string {
      return status === 'passed' ? 'check_circle' : status === 'failed' ? 'cancel' : 'remove_circle_outline';
    },
    statusColor(status: 'passed' | 'failed' | 'skipped'): string {
      return status === 'passed' ? 'positive' : status === 'failed' ? 'negative' : 'grey';
    },
    // Open the test dialog where the user supplies a document to run against.
    openTestDialog() {
      if (!this.validate()) {
        return;
      }
      this.testDocMode = 'id';
      this.testDocId = '';
      this.testResult = null;
      this.testJsonKey += 1; // fresh, empty Ace editor each open
      this.testDialogOpen = true;
    },
    // Dry-run the rule against the document supplied in the dialog. The API
    // wants EXACTLY ONE of `rule_id` (saved rule) or `rule` (draft), and the
    // document as EITHER `document_id` OR inline `doc_data`.
    async executeTest() {
      // Build the document target from the chosen mode; validate the input.
      const target: { document_id?: string; doc_data?: Record<string, unknown> } = {};
      if (this.testDocMode === 'id') {
        const id = this.testDocId.trim();
        if (!id) {
          notify.warning(this.$t('test_document_id_required'));
          return;
        }
        target.document_id = id;
      } else {
        const editor = this.$refs.testJsonEditor as { getJson: () => string } | undefined;
        const raw = (editor?.getJson() || '').trim();
        if (!raw) {
          notify.warning(this.$t('test_document_json_required'));
          return;
        }
        try {
          target.doc_data = JSON.parse(raw);
        } catch {
          notify.warning(this.$t('test_document_json_invalid'));
          return;
        }
      }

      try {
        this.testing = true;
        let payload: TestValidationRulePayload;
        if (this.isEdit) {
          payload = { rule_id: this.rule_id, ...target };
        } else {
          const core = assembleApiCore(this.model);
          const rule_key = this.model.rule_key || slugify(this.model.display_name);
          payload = {
            rule: { ...core, doc_type: this.doc_type_key, scope: this.model.scope, rule_key },
            ...target,
          };
        }
        // Keep the dialog open and render the outcome inline instead of
        // closing — the user can tweak the document and re-run.
        this.testResult = await customValidationRulesApiService.test<TestValidationRuleResult>(payload);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.testing = false;
      }
    },
    goBack() {
      this.$router.push('/settings/custom-validation-rules/' + this.doc_type_key);
    },
    // Fork this system-default rule into an editable org copy and reopen the
    // builder on that copy. The backend returns a new rule (same rule_key, new
    // id) which we hand over via router state to prefill without a refetch.
    async customizeRule() {
      if (!this.rule_id) {
        return;
      }
      try {
        this.customizing = true;
        const override = await customValidationRulesApiService.customize(this.rule_id);
        this.$router.push({
          path: '/settings/custom-validation-rules/' + this.doc_type_key + '/' + override.id,
          state: { rule: JSON.parse(JSON.stringify(override)) },
        });
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.customizing = false;
      }
    },
  },
  // setup() hosts only the useRuleKey composable (composables must run here) plus
  // the state it reads reactively. rule_id / isReadOnly aren't props, so they live
  // here rather than data — but stay writable as this.rule_id / this.isReadOnly
  // from the Options methods (mounted, applyRule). isEdit is an Options computed.
  setup() {
    const model = ref<BuilderModel>(emptyModel());
    const rule_id = ref('');
    // System-default rules (source === 'system_default') are shown read-only.
    const isReadOnly = ref(false);
    const ruleKey = useRuleKey({
      getName: () => model.value.display_name,
      setKey: (value) => {
        model.value.rule_key = value;
      },
      isEdit: () => !!rule_id.value,
      isReadOnly: () => isReadOnly.value,
    });
    // Shared LOV store — feeds the allowed-values "List of Values" picker.
    const fieldValuesStore = useFieldValuesSettingsStore();
    const { lov_list } = storeToRefs(fieldValuesStore);
    const { getLovList } = fieldValuesStore;
    return {
      model,
      rule_id,
      isReadOnly,
      ...ruleKey,
      lov_list,
      getLovList,
      saving: ref(false),
      testing: ref(false),
      customizing: ref(false),
    };
  },
});
</script>

